try:
    start = time.time()
    headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"}
    r = requests.get(url, headers=headers, timeout=12)
    load_time = round(time.time() - start, 2)
    soup = BeautifulSoup(r.text, "html.parser")

    title = soup.find("title")
    meta_desc = soup.find("meta", attrs={"name": "description"})
    h1 = soup.find_all("h1")
    viewport = soup.find("meta", attrs={"name": "viewport"})
    canonical = soup.find("link", attrs={"rel": "canonical"})

    issues = []
    seo_score = 10

    if not title or not title.text.strip():
        issues.append("Kein <title>-Tag"); seo_score -= 3
    if not meta_desc or not meta_desc.get("content", "").strip():
        issues.append("Keine Meta-Description"); seo_score -= 2
    if len(h1) == 0:
        issues.append("Kein H1-Tag"); seo_score -= 2
    if not viewport or "width=device-width" not in viewport.get("content", ""):
        issues.append("Kein responsives Viewport"); seo_score -= 1
    if not canonical:
        issues.append("Kein Canonical-Tag"); seo_score -= 1
    if load_time > 3:
        issues.append(f"Ladezeit zu langsam ({load_time}s)")

    return {
        "seo_score": max(0, seo_score),
        "issues": issues or ["Keine kritischen SEO-Probleme"],
        "load_time": load_time,
        "title_length": len(title.text.strip()) if title else 0
    }
except Exception as e:
    return {"seo_score": 0, "issues": [f"Fehler beim Abruf: {str(e)[:80]}"], "load_time": 0}

